//! The design tokens as CSS variables (UIT-07, UI-11): generated from `otaq-view`'s theme data, never copied by
//! hand, into `ui/src/theme/generated/` (committed; that folder holds only generated files):
//!
//! - `tokens.css`: the fonts, spacing, radius, density and type scale on `:root`, and one block per theme,
//!   `[data-theme="<key>"]`, with its 39 colour tokens and 16 terminal colours (`--bg-app`, `--ansi-0`, …). The page
//!   sets `data-theme` on the root element; any element can carry it to show another theme inside (a swatch page).
//! - `tokens.ts`: the token names, the theme keys and the two first-launch themes, for code that lists them.
//!
//! One command regenerates both:
//!
//! ```sh
//! cargo test -p otaq-desktop regenerate_stylesheet -- --ignored
//! ```
//!
//! `stylesheet_is_fresh` (part of `cargo test`, so of `scripts/check.sh`) fails when the committed files differ, and
//! `the_css_holds_the_rust_palette` reads the committed CSS back and compares every value with the Rust table, which
//! T-0207's `token_values_match_the_design` keeps pinned to `crewboard.pen`.

use std::fmt::Write;

use otaq_core::board::settings::ThemeSetting;
use otaq_view::theme::{
    self, Appearance, Colors, FONT_MONO, FONT_UI, ThemeId, density, radius, space, text,
};

/// The committed folder, relative to this crate.
const FOLDER: &str = "ui/src/theme/generated";

/// The first line of each file: where it comes from and how to regenerate it.
fn header() -> String {
    format!(
        "Generated by src/stylesheet.rs from the view crate's theme data. Don't edit; run \
         `cargo test -p {} regenerate_stylesheet -- --ignored`.",
        env!("CARGO_PKG_NAME")
    )
}

/// The theme's key: its stored setting value (`tokyo-night`).
fn key(id: ThemeId) -> &'static str {
    id.stored().as_str()
}

/// `0xRRGGBBAA` as CSS hex, without the alpha when it is opaque.
fn hex(rgba: u32) -> String {
    if rgba & 0xFF == 0xFF {
        format!("#{:06x}", rgba >> 8)
    } else {
        format!("#{rgba:08x}")
    }
}

/// A number as CSS writes it: `4`, `1.35`, `-0.3`.
fn num(value: f32) -> String {
    format!("{value}")
}

fn tokens_css() -> String {
    let mut css = format!("/* {} */\n\n:root {{\n", header());
    let mut var = |name: &str, value: String| {
        writeln!(css, "  --{name}: {value};").unwrap();
    };
    var("font-ui", format!("\"{FONT_UI}\", system-ui, sans-serif"));
    var(
        "font-mono",
        format!("\"{FONT_MONO}\", ui-monospace, monospace"),
    );
    for (n, value) in [
        space::S1,
        space::S2,
        space::S3,
        space::S4,
        space::S5,
        space::S6,
    ]
    .into_iter()
    .enumerate()
    {
        var(&format!("s-{}", n + 1), format!("{}px", num(value)));
    }
    for (name, value) in [
        ("r-sm", radius::SM),
        ("r-md", radius::MD),
        ("r-lg", radius::LG),
        ("r-dialog", radius::DIALOG),
        ("column-width", density::COLUMN),
        ("column-width-compact", density::COLUMN_COMPACT),
        ("card-padding-y", density::CARD_PADDING.0),
        ("card-padding-x", density::CARD_PADDING.1),
        ("header-height", density::HEADER),
        ("row-height", density::ROW),
        ("icon-size", 14.),
    ] {
        var(name, format!("{}px", num(value)));
    }
    // Each step as a `font` shorthand (`font: var(--text-body)`) plus its letter spacing.
    for (name, style) in text::ALL {
        let family = if style.mono { "mono" } else { "ui" };
        let line_height = style.line_height.map_or("normal".into(), num);
        var(
            &format!("text-{name}"),
            format!(
                "{} {}px/{line_height} var(--font-{family})",
                style.weight,
                num(style.size)
            ),
        );
        var(
            &format!("text-{name}-tracking"),
            format!("{}px", num(style.letter_spacing)),
        );
    }
    css.push_str("}\n");
    for id in ThemeId::ALL {
        let scheme = match id.appearance() {
            Appearance::Light => "light",
            Appearance::Dark => "dark",
        };
        write!(
            css,
            "\n/* {} */\n[data-theme=\"{}\"] {{\n  color-scheme: {scheme};\n",
            id.name(),
            key(id)
        )
        .unwrap();
        let colors = Colors::new(id);
        for name in Colors::<u32>::NAMES {
            let value = colors.get(name).expect("every token resolves");
            writeln!(css, "  --{name}: {};", hex(value)).unwrap();
        }
        for (n, rgb) in theme::ansi(id).into_iter().enumerate() {
            writeln!(css, "  --ansi-{n}: {};", hex((rgb << 8) | 0xFF)).unwrap();
        }
        css.push_str("}\n");
    }
    css
}

fn tokens_ts() -> String {
    let list = |items: Vec<&str>| {
        items
            .iter()
            .map(|i| format!("  \"{i}\",\n"))
            .collect::<String>()
    };
    let first = |os| key(ThemeId::from_setting(ThemeSetting::default(), os));
    format!(
        "// {}\n\n\
         /** The 39 colour tokens, each a CSS variable (`--bg-app`), in the design's order. */\n\
         export const COLOR_TOKENS = [\n{}] as const;\n\n\
         /** The 15 themes by key, the value of `data-theme`, in the design's order. */\n\
         export const THEME_KEYS = [\n{}] as const;\n\n\
         export type ThemeKey = (typeof THEME_KEYS)[number];\n\n\
         /** The theme a fresh data folder starts with, by the OS appearance (d0070). */\n\
         export const FIRST_LAUNCH: {{ readonly dark: ThemeKey; readonly light: ThemeKey }} = {{\n  \
         dark: \"{}\",\n  light: \"{}\",\n}};\n",
        header(),
        list(Colors::<u32>::NAMES.to_vec()),
        list(ThemeId::ALL.into_iter().map(key).collect()),
        first(Appearance::Dark),
        first(Appearance::Light),
    )
}

/// Every generated file by name, with its text.
fn generate() -> [(&'static str, String); 2] {
    [("tokens.css", tokens_css()), ("tokens.ts", tokens_ts())]
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeMap;
    use std::path::{Path, PathBuf};

    use otaq_core::naming;

    use super::*;

    fn committed() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join(FOLDER)
    }

    fn read(name: &str) -> String {
        std::fs::read_to_string(committed().join(name))
            .unwrap_or_default()
            .replace("\r\n", "\n")
    }

    #[test]
    fn stylesheet_is_fresh() {
        let stale: Vec<&str> = generate()
            .iter()
            .filter(|(name, text)| read(name) != *text)
            .map(|(name, _)| *name)
            .collect();
        assert!(
            stale.is_empty(),
            "{FOLDER} is stale: {}. Run `cargo test -p {} regenerate_stylesheet -- --ignored` to regenerate.",
            stale.join(", "),
            env!("CARGO_PKG_NAME"),
        );
    }

    /// The one command that regenerates the folder (see the module docs).
    #[test]
    #[ignore = "writes into the source tree; run on purpose to regenerate"]
    fn regenerate_stylesheet() {
        let dir = committed();
        std::fs::create_dir_all(&dir).unwrap();
        for (name, text) in generate() {
            std::fs::write(dir.join(name), text).unwrap();
        }
    }

    /// The committed CSS, read back: each theme block's variables by name, with their values as RGBA.
    fn themes_in_css(css: &str) -> BTreeMap<String, BTreeMap<String, u32>> {
        let mut themes = BTreeMap::new();
        for block in css.split("[data-theme=\"").skip(1) {
            let (key, body) = block.split_once("\"]").unwrap();
            let body = &body[..body.find('}').unwrap()];
            let vars = body
                .lines()
                .filter_map(|line| line.trim().strip_prefix("--"))
                .map(|decl| {
                    let (name, value) = decl.trim_end_matches(';').split_once(": ").unwrap();
                    let digits = value.trim_start_matches('#');
                    let v = u32::from_str_radix(digits, 16).unwrap();
                    let rgba = if digits.len() == 6 {
                        (v << 8) | 0xFF
                    } else {
                        v
                    };
                    (name.to_owned(), rgba)
                })
                .collect();
            themes.insert(key.to_owned(), vars);
        }
        themes
    }

    #[test]
    fn the_css_holds_the_rust_palette() {
        let themes = themes_in_css(&read("tokens.css"));
        assert_eq!(themes.len(), 15);
        for id in ThemeId::ALL {
            let vars = &themes[key(id)];
            assert_eq!(vars.len(), 39 + 16, "{id:?}");
            let colors = Colors::new(id);
            for name in Colors::<u32>::NAMES {
                assert_eq!(Some(vars[*name]), colors.get(name), "{name} ({id:?})");
            }
            for (n, rgb) in theme::ansi(id).into_iter().enumerate() {
                assert_eq!(vars[&format!("ansi-{n}")] >> 8, rgb, "ansi-{n} ({id:?})");
            }
        }
    }

    #[test]
    fn values_are_written_as_css() {
        assert_eq!(hex(0x4C57D6FF), "#4c57d6");
        assert_eq!(hex(0x4C57D633), "#4c57d633");
        assert_eq!(num(4.), "4");
        assert_eq!(num(-0.3), "-0.3");
        let css = tokens_css();
        assert!(css.contains("  --text-display: 600 20px/normal var(--font-ui);\n"));
        assert!(css.contains("  --text-display-tracking: -0.3px;\n"));
        assert!(css.contains("  --text-terminal: 400 13px/1.45 var(--font-mono);\n"));
        assert!(css.contains("  --s-6: 32px;\n"));
        assert!(css.contains("[data-theme=\"tokyo-night\"] {\n  color-scheme: dark;\n"));
        let ts = tokens_ts();
        let first = format!(
            "  dark: \"{}\",\n  light: \"{}\",\n",
            naming::THEME_DARK,
            naming::THEME_LIGHT
        );
        assert!(ts.contains(&first));
    }
}
